-- ES/DE/FR translations for the rest of Belgium's deep-dive content,
-- including the penalty-row translations (first country in this batch
-- with a genuine tabular penalty schedule).

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Peppol descentralizado de 4 esquinas', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los requisitos del Punto de Acceso, la aplicación de sanciones y el despliegue del reporte electrónico de 2028 continúan evolucionando — confirme los requisitos actuales directamente con el SPF Finanzas o con el Punto de Acceso Peppol que haya elegido antes de construir una integración.', 'Bélgica construyó su mandato B2B directamente sobre una infraestructura que ya llevaba años implementando para el sector público — la facturación electrónica B2G llegó primero, por fases, antes de que el B2B llegara de una sola vez.', 'Bélgica se apoya casi por completo en el ecosistema Peppol existente en lugar de inventar un formato nacional desde cero.', 'No existe una plataforma gubernamental belga de compensación para facturas B2B — Mercurius gestiona únicamente el B2G. El tráfico B2B circula de igual a igual a través de Peppol.', 'No existe una "cuenta de facturación electrónica" independiente que abrir con el SPF Finanzas — el registro se realiza a través de un Punto de Acceso comercial, utilizando su número de empresa existente.', 'La escala de sanciones de Bélgica es progresiva y se aplica por infracción, no por factura — lo que la mantiene manejable si resuelve rápidamente el problema subyacente.' FROM countries WHERE name_en = 'Belgium';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Dezentrales Peppol-4-Corner-Modell', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Anforderungen an Access Points, die Durchsetzung von Bußgeldern und der Aufbau des E-Reportings 2028 entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt beim FÖD Finanzen oder Ihrem gewählten Peppol Access Point, bevor Sie eine Integration aufbauen.', 'Belgien hat seine B2B-Pflicht direkt auf einer Infrastruktur aufgebaut, die es bereits jahrelang für den öffentlichen Sektor ausgerollt hatte — die B2G-E-Rechnung kam zuerst, stufenweise, bevor B2B auf einen Schlag kam.', 'Belgien stützt sich fast vollständig auf das bestehende Peppol-Ökosystem, anstatt ein nationales Format von Grund auf neu zu erfinden.', 'Es gibt keine belgische staatliche Clearing-Plattform für B2B-Rechnungen — Mercurius verarbeitet nur B2G. B2B-Verkehr läuft Peer-to-Peer über Peppol.', 'Es gibt kein separates "E-Invoicing-Konto", das beim FÖD Finanzen eröffnet werden muss — die Registrierung erfolgt über einen kommerziellen Access Point, unter Verwendung Ihrer bestehenden Unternehmensnummer.', 'Belgiens Sanktionsstaffel ist progressiv und gilt pro Verstoß — nicht pro Rechnung — was sie überschaubar hält, wenn Sie das zugrunde liegende Problem schnell beheben.' FROM countries WHERE name_en = 'Belgium';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Peppol décentralisé à 4 coins', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les exigences relatives aux Access Points, l''application des sanctions et le déploiement de la déclaration électronique 2028 continuent d''évoluer — confirmez les exigences actuelles directement auprès du SPF Finances ou de votre Access Point Peppol avant de construire une intégration.', 'La Belgique a bâti son obligation B2B directement sur une infrastructure qu''elle avait déjà mis des années à déployer pour le secteur public — la facturation électronique B2G est arrivée en premier, par étapes, avant que le B2B n''arrive d''un coup.', 'La Belgique s''appuie presque entièrement sur l''écosystème Peppol existant plutôt que d''inventer un format national de toutes pièces.', 'Il n''existe aucune plateforme gouvernementale belge de contrôle pour les factures B2B — Mercurius ne gère que le B2G. Le trafic B2B circule de pair à pair via Peppol.', 'Il n''existe pas de "compte de facturation électronique" distinct à ouvrir auprès du SPF Finances — l''inscription se fait via un Access Point commercial, en utilisant votre numéro d''entreprise existant.', 'L''échelle de sanctions belge est progressive et s''applique par infraction — et non par facture — ce qui la rend gérable si vous corrigez rapidement le problème sous-jacent.' FROM countries WHERE name_en = 'Belgium';

