INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato predeterminado", "Peppol BIS Billing 3.0 (UBL 2.1)"], ["Modelo semántico europeo", "EN 16931"], ["CIUS nacional", "Ninguno — utiliza directamente la CIUS de Peppol BIS"], ["Sintaxis alternativa", "UN/CEFACT CII D16B (por acuerdo bilateral)"]]', 'Bélgica es uno de los pocos mercados de la UE que no ha añadido su propia CIUS nacional sobre Peppol BIS — utilizar el perfil europeo estándar tal cual es plenamente conforme, lo que mantiene simple el comercio transfronterizo.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Format & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Standardformat", "Peppol BIS Billing 3.0 (UBL 2.1)"], ["Europäisches Semantikmodell", "EN 16931"], ["Nationale CIUS", "Keine — verwendet direkt die Peppol-BIS-CIUS"], ["Alternative Syntax", "UN/CEFACT CII D16B (nach bilateraler Vereinbarung)"]]', 'Belgien ist einer der wenigen EU-Märkte, der keine eigene nationale CIUS über die Peppol BIS gelegt hat — die Verwendung des europäischen Standardprofils unverändert ist voll konform, was den grenzüberschreitenden Handel einfach hält.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Format & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format par défaut", "Peppol BIS Billing 3.0 (UBL 2.1)"], ["Modèle sémantique européen", "EN 16931"], ["CIUS nationale", "Aucune — utilise directement la CIUS Peppol BIS"], ["Syntaxe alternative", "UN/CEFACT CII D16B (par accord bilatéral)"]]', 'La Belgique est l''un des rares marchés de l''UE à ne pas avoir superposé sa propre CIUS nationale à Peppol BIS — utiliser le profil européen standard tel quel est pleinement conforme, ce qui simplifie le commerce transfrontalier.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Format & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores empresariales', '[["Esquema preferido", "0208 (número de empresa KBO/BCE)"], ["Esquema alternativo", "9925 (número de IVA belga, BE + 10 dígitos)"], ["Consulta de directorio", "Búsqueda pública KBO + Directorio Peppol"]]', 'El esquema 9925 es un "valor extendido" de Peppol y no un código ISO 6523 oficial — es válido para el enrutamiento en la red, pero tiene un soporte más limitado que el 0208. Si tiene un número KBO (como casi todas las empresas registradas, incluidas las empresas extranjeras que operan en Bélgica), utilice el 0208.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Business identifiers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Geschäftskennungen', '[["Bevorzugtes Schema", "0208 (KBO/BCE-Unternehmensnummer)"], ["Alternatives Schema", "9925 (belgische USt-Nummer, BE + 10 Ziffern)"], ["Verzeichnisabfrage", "KBO Public Search + Peppol-Verzeichnis"]]', 'Schema 9925 ist ein "erweiterter Wert" von Peppol und kein offizieller ISO-6523-Code — er ist für das Netzwerk-Routing gültig, wird aber weniger breit unterstützt als 0208. Wenn Sie eine KBO-Nummer haben (das gilt für fast jedes registrierte Unternehmen, auch für ausländische Unternehmen mit Geschäftstätigkeit in Belgien), verwenden Sie 0208.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Business identifiers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants d''entreprise', '[["Schéma privilégié", "0208 (numéro d''entreprise KBO/BCE)"], ["Schéma alternatif", "9925 (numéro de TVA belge, BE + 10 chiffres)"], ["Recherche d''annuaire", "Recherche publique KBO + Annuaire Peppol"]]', 'Le schéma 9925 est une « valeur étendue » Peppol plutôt qu''un code ISO 6523 officiel — il est valable pour le routage réseau mais bénéficie d''une prise en charge plus limitée que le 0208. Si vous disposez d''un numéro KBO (c''est le cas de presque toutes les entreprises enregistrées, y compris les entreprises étrangères opérant en Belgique), utilisez le 0208.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Business identifiers';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Campos obligatorios de la factura', '[["Encabezado", "Número de factura único, fecha de emisión ISO 8601, moneda, referencia de pedido"], ["Datos de las partes", "Razón social, n.º de IVA, KBO/BCE, dirección, ID de participante Peppol"], ["Nivel de línea", "Código de categoría de IVA (S/Z/E), tipo, cantidad, precio unitario, total de línea"]]', 'Los números de factura duplicados y la categorización de IVA incorrecta a nivel de línea son las dos causas más comunes de fallo en la validación del Punto de Acceso — ambas se comprueban automáticamente antes de que la factura llegue siquiera a la red.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Mandatory invoice fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtfelder der Rechnung', '[["Kopfdaten", "Eindeutige Rechnungsnummer, Ausstellungsdatum nach ISO 8601, Währung, Bestellreferenz"], ["Parteidaten", "Firmenname, USt-Nr., KBO/BCE, Adresse, Peppol-Teilnehmer-ID"], ["Positionsebene", "USt-Kategoriecode (S/Z/E), Satz, Menge, Einzelpreis, Positionssumme"]]', 'Doppelte Rechnungsnummern und fehlerhafte USt-Kategorisierung auf Positionsebene sind die beiden häufigsten Ursachen für ein Scheitern der Access-Point-Validierung — beide werden automatisch geprüft, bevor die Rechnung überhaupt ins Netzwerk gelangt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Mandatory invoice fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Champs obligatoires de la facture', '[["En-tête", "Numéro de facture unique, date d''émission ISO 8601, devise, référence de commande"], ["Données des parties", "Raison sociale, n° de TVA, KBO/BCE, adresse, ID participant Peppol"], ["Niveau ligne", "Code de catégorie de TVA (S/Z/E), taux, quantité, prix unitaire, total de ligne"]]', 'Les numéros de facture en double et la catégorisation de TVA incorrecte au niveau des lignes sont les deux causes les plus courantes d''échec de validation à l''Access Point — les deux sont vérifiées automatiquement avant même que la facture n''atteigne le réseau.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Mandatory invoice fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Archivo', '[["Período de conservación", "Mínimo 7 años"], ["Qué conservar", "XML original + registros de procesamiento del Punto de Acceso"]]', 'Si cambia de proveedor de Punto de Acceso, descargue sus archivos XML originales y los registros de procesamiento antes de cerrar su cuenta antigua — puede perder el acceso al portal con las facturas históricas una vez que se vaya, y es usted quien las necesitará para una futura auditoría.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Archivierung', '[["Aufbewahrungsfrist", "Mindestens 7 Jahre"], ["Was aufzubewahren ist", "Original-XML + Verarbeitungsprotokolle des Access Points"]]', 'Wenn Sie den Access-Point-Anbieter wechseln, laden Sie Ihre originalen XML-Dateien und Verarbeitungsprotokolle herunter, bevor Sie Ihr altes Konto schließen — Sie können nach dem Wechsel den Portalzugang zu historischen Rechnungen verlieren, und Sie sind es, der sie für eine künftige Prüfung benötigt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Archivage', '[["Durée de conservation", "7 ans minimum"], ["Ce qu''il faut conserver", "XML original + journaux de traitement de l''Access Point"]]', 'Si vous changez de prestataire Access Point, téléchargez vos fichiers XML originaux et vos journaux de traitement avant de fermer votre ancien compte — vous risquez de perdre l''accès au portail pour les factures historiques une fois parti, et c''est vous qui en aurez besoin lors d''un futur audit.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo B2B", "Peppol de 4 esquinas (descentralizado)"], ["Modelo B2G", "Mercurius (centro central, alineado con Peppol)"], ["Autoridad gubernamental", "SPF Finanzas"]]', 'No confunda ambos: Mercurius es específicamente para facturar a organismos públicos. Las facturas B2B ordinarias circulan directamente entre los Puntos de Acceso de las empresas y nunca pasan por Mercurius.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Network model';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["B2B-Modell", "Peppol 4-Corner (dezentral)"], ["B2G-Modell", "Mercurius (zentraler Hub, Peppol-ausgerichtet)"], ["Staatliche Behörde", "FÖD Finanzen"]]', 'Verwechseln Sie die beiden nicht: Mercurius dient ausschließlich der Rechnungsstellung an öffentliche Stellen. Gewöhnliche B2B-Rechnungen laufen direkt zwischen den Access Points der Unternehmen und berühren Mercurius überhaupt nicht.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Network model';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle B2B", "Peppol à 4 coins (décentralisé)"], ["Modèle B2G", "Mercurius (hub central, aligné sur Peppol)"], ["Autorité gouvernementale", "SPF Finances"]]', 'Ne confondez pas les deux : Mercurius sert spécifiquement à facturer les organismes publics. Les factures B2B ordinaires circulent directement entre les Access Points des entreprises et ne passent jamais par Mercurius.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Network model';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Conectividad del Punto de Acceso', '[["Requisito", "Punto de Acceso Peppol certificado"], ["Proveedores habituales", "Muchos ERP incluyen soporte integrado (Exact, Yuki, Billit, Teamleader, Octopus y otros)"], ["Punto de validación", "Las comprobaciones Schematron se ejecutan en el Punto de Acceso antes de entrar en la red"]]', 'Un número de empresa solo puede vincularse a un Punto de Acceso a la vez. Para cambiar de proveedor, su Punto de Acceso anterior debe primero "despublicar" su número KBO del directorio antes de que su nuevo proveedor pueda registrarlo.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Access Point connectivity';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Access-Point-Anbindung', '[["Voraussetzung", "Zertifizierter Peppol Access Point"], ["Gängige Anbieter", "Viele ERP-Systeme bieten integrierte Unterstützung (Exact, Yuki, Billit, Teamleader, Octopus und andere)"], ["Validierungspunkt", "Schematron-Prüfungen laufen am Access Point vor dem Eintritt ins Netzwerk"]]', 'Eine Unternehmensnummer kann jeweils nur mit einem Access Point verknüpft sein. Um den Anbieter zu wechseln, muss Ihr alter Access Point Ihre KBO-Nummer zunächst aus dem Verzeichnis "abmelden", bevor Ihr neuer Anbieter sie registrieren kann.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Access Point connectivity';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Connectivité de l''Access Point', '[["Exigence", "Access Point Peppol certifié"], ["Fournisseurs courants", "De nombreux ERP intègrent un support natif (Exact, Yuki, Billit, Teamleader, Octopus et autres)"], ["Point de validation", "Les contrôles Schematron s''exécutent à l''Access Point avant l''entrée sur le réseau"]]', 'Un numéro d''entreprise ne peut être lié qu''à un seul Access Point à la fois. Pour changer de prestataire, votre ancien Access Point doit d''abord « désinscrire » votre numéro KBO de l''annuaire avant que votre nouveau prestataire puisse l''enregistrer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Access Point connectivity';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Canales alternativos', '[["EDI (p. ej. EDIFACT)", "Permitido solo por acuerdo mutuo"], ["Condición", "Debe seguir siendo conforme con EN 16931"]]', 'En la práctica, casi todo el mundo utiliza por defecto Peppol BIS Billing 3.0, ya que no requiere ningún acuerdo bilateral entre socios comerciales — dos empresas cualesquiera conectadas a Peppol pueden intercambiar facturas automáticamente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Alternative channels';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Alternative Kanäle', '[["EDI (z. B. EDIFACT)", "Nur nach gegenseitiger Vereinbarung zulässig"], ["Bedingung", "Muss weiterhin EN-16931-konform sein"]]', 'In der Praxis greifen fast alle standardmäßig auf Peppol BIS Billing 3.0 zurück, da hierfür keine bilaterale Vereinbarung zwischen Handelspartnern nötig ist — beliebige zwei mit Peppol verbundene Unternehmen können automatisch Rechnungen austauschen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Alternative channels';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Canaux alternatifs', '[["EDI (par ex. EDIFACT)", "Autorisé uniquement par accord mutuel"], ["Condition", "Doit rester conforme à l''EN 16931"]]', 'En pratique, presque tout le monde utilise par défaut Peppol BIS Billing 3.0, car il ne nécessite aucun accord bilatéral entre partenaires commerciaux — deux entreprises quelconques connectées à Peppol peuvent échanger des factures automatiquement.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Alternative channels';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Próximamente en 2028', '[["Modelo", "Peppol de 5 esquinas (añade un tramo de reporte a la autoridad fiscal)"], ["Finalidad", "Reporte de IVA casi en tiempo real"]]', 'El modelo de 5 esquinas se construye directamente sobre la red de 4 esquinas ya existente — si su integración con el Punto de Acceso es sólida hoy, la actualización de 2028 debería ser sobre todo un problema de su proveedor, no suyo.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Coming in 2028';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Ab 2028', '[["Modell", "Peppol 5-Corner (fügt einen Meldeweg zur Steuerbehörde hinzu)"], ["Zweck", "Nahezu-Echtzeit-Umsatzsteuermeldung"]]', 'Das 5-Corner-Modell baut direkt auf dem bereits bestehenden 4-Corner-Netzwerk auf — wenn Ihre Access-Point-Integration heute solide ist, sollte das Upgrade 2028 größtenteils ein Problem Ihres Anbieters sein, nicht Ihres.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Coming in 2028';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'À venir en 2028', '[["Modèle", "Peppol à 5 coins (ajoute un volet de déclaration à l''administration fiscale)"], ["Objectif", "Déclaration de TVA quasi en temps réel"]]', 'Le modèle à 5 coins s''appuie directement sur le réseau à 4 coins déjà en place — si votre intégration Access Point est solide aujourd''hui, la mise à niveau de 2028 devrait surtout être le problème de votre prestataire, pas le vôtre.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'scope_transmission' AND dct.title = 'Coming in 2028';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🏛️ El B2G sigue siendo independiente', NULL, NULL, 'Si abastece a organismos públicos belgas, esa obligación se gestiona a través de Mercurius y se aplica desde 2019 (proveedores) — no desaparece solo porque el mandato B2B haya llegado junto a ella.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '🏛️ B2G stays separate';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🏛️ B2G bleibt getrennt', NULL, NULL, 'Wenn Sie belgische öffentliche Stellen beliefern, läuft diese Pflicht über Mercurius und gilt bereits seit 2019 (für Lieferanten) — sie verschwindet nicht nur, weil das B2B-Mandat nun zusätzlich gilt.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '🏛️ B2G stays separate';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🏛️ Le B2G reste distinct', NULL, NULL, 'Si vous fournissez des organismes publics belges, cette obligation passe par Mercurius et s''applique depuis 2019 (fournisseurs) — elle ne disparaît pas simplement parce que l''obligation B2B est arrivée en parallèle.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '🏛️ B2G stays separate';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🪪 Exenciones limitadas', NULL, NULL, 'Un pequeño número de estatus específicos de IVA y tipos de transacción quedan fuera del ámbito B2B nacional — en caso de duda, los factores decisivos son siempre si el proveedor, el cliente y la transacción son todos B2B nacionales belgas.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '🪪 Narrow exemptions';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🪪 Enge Ausnahmen', NULL, NULL, 'Eine Handvoll spezifischer Umsatzsteuerstatus und Transaktionsarten fällt nicht unter den inländischen B2B-Anwendungsbereich — im Zweifel sind die entscheidenden Faktoren immer, ob Lieferant, Kunde und Transaktion allesamt inländisches belgisches B2B sind.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '🪪 Narrow exemptions';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🪪 Exemptions restreintes', NULL, NULL, 'Une poignée de statuts de TVA et de types de transactions spécifiques échappent au champ B2B national — en cas de doute, les facteurs déterminants sont toujours de savoir si le fournisseur, le client et la transaction sont tous du B2B national belge.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '🪪 Narrow exemptions';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📶 Estabilidad de la red', NULL, NULL, 'Las primeras revisiones tras la entrada en vigor del mandato mostraron que la propia red Peppol funcionaba de forma fiable — la mayoría de los problemas reales se debían a lagunas de registro o a una mala calidad de los datos en empresas individuales, no a la infraestructura.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '📶 Network stability';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📶 Netzwerkstabilität', NULL, NULL, 'Frühe Überprüfungen nach Inkrafttreten der Pflicht zeigten, dass das Peppol-Netzwerk selbst zuverlässig funktionierte — die meisten realen Probleme ließen sich auf Registrierungslücken oder schlechte Datenqualität bei einzelnen Unternehmen zurückführen, nicht auf die Infrastruktur.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '📶 Network stability';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📶 Stabilité du réseau', NULL, NULL, 'Les premiers bilans après l''entrée en vigueur de l''obligation ont montré que le réseau Peppol lui-même fonctionnait de manière fiable — la plupart des problèmes réels provenaient de lacunes d''inscription ou d''une mauvaise qualité des données au niveau des entreprises, et non de l''infrastructure.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Belgium' AND dc.section = 'penalties_related' AND dct.title = '📶 Network stability';

