INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su número de empresa KBO/BCE', 'Consulte la Búsqueda Pública KBO si no está seguro de su número — casi todas las entidades registradas a efectos de IVA que operan en Bélgica tienen uno, incluidas las empresas extranjeras con un establecimiento belga.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Confirm your KBO/BCE enterprise number';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihre KBO/BCE-Unternehmensnummer', 'Prüfen Sie die KBO Public Search, wenn Sie sich Ihrer Nummer nicht sicher sind — fast alle umsatzsteuerlich registrierten Unternehmen, die in Belgien tätig sind, besitzen eine, einschließlich ausländischer Unternehmen mit einer belgischen Niederlassung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Confirm your KBO/BCE enterprise number';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez votre numéro d''entreprise KBO/BCE', 'Consultez la Recherche publique KBO si vous n''êtes pas sûr de votre numéro — presque toutes les entités assujetties à la TVA opérant en Belgique en possèdent un, y compris les entreprises étrangères disposant d''un établissement belge.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Confirm your KBO/BCE enterprise number';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija un Punto de Acceso Peppol certificado', 'Elija un proveedor independiente o confirme que su software de contabilidad/ERP existente ya incluye conectividad Peppol — muchas plataformas belgas habituales la incluyen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Choose a certified Peppol Access Point';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie einen zertifizierten Peppol Access Point', 'Wählen Sie einen eigenständigen Anbieter oder prüfen Sie, ob Ihre bestehende Buchhaltungs-/ERP-Software bereits Peppol-Konnektivität bietet — viele gängige belgische Plattformen tun dies.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Choose a certified Peppol Access Point';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez un Access Point Peppol certifié', 'Choisissez un prestataire indépendant ou vérifiez que votre logiciel de comptabilité/ERP actuel inclut déjà la connectivité Peppol — de nombreuses plateformes belges courantes le proposent.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Choose a certified Peppol Access Point';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Deje que su Punto de Acceso verifique y publique su ID', 'Su proveedor verifica los datos de su empresa y publica su ID de participante Peppol (esquema 0208 + número KBO) en el Directorio Peppol global, haciéndole localizable para cualquier socio comercial.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Let your Access Point verify and publish your ID';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Lassen Sie Ihre ID von Ihrem Access Point verifizieren und veröffentlichen', 'Ihr Anbieter überprüft Ihre Unternehmensdaten und veröffentlicht Ihre Peppol-Teilnehmer-ID (Schema 0208 + KBO-Nummer) im globalen Peppol-Verzeichnis, wodurch Sie für jeden Handelspartner auffindbar werden.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Let your Access Point verify and publish your ID';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Laissez votre Access Point vérifier et publier votre ID', 'Votre prestataire vérifie vos informations d''entreprise et publie votre ID participant Peppol (schéma 0208 + numéro KBO) dans l''Annuaire Peppol mondial, vous rendant ainsi visible pour tout partenaire commercial.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Let your Access Point verify and publish your ID';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pruebe la generación de facturas frente a BIS Billing 3.0', 'Valide que su ERP produce XML UBL correctamente estructurado — números de factura únicos, códigos de categoría de IVA correctos a nivel de línea e identificación completa de las partes. La mayoría de los Puntos de Acceso ofrecen un entorno de pruebas para esto.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Test invoice generation against BIS Billing 3.0';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie die Rechnungserstellung gegen BIS Billing 3.0', 'Prüfen Sie, ob Ihr ERP korrekt strukturiertes UBL-XML erzeugt — eindeutige Rechnungsnummern, korrekte USt-Kategoriecodes auf Positionsebene und vollständige Identifikation der Parteien. Die meisten Access Points bieten hierfür eine Sandbox.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Test invoice generation against BIS Billing 3.0';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez la génération de factures par rapport à BIS Billing 3.0', 'Vérifiez que votre ERP produit un XML UBL correctement structuré — numéros de facture uniques, codes de catégorie de TVA corrects au niveau des lignes et identification complète des parties. La plupart des Access Points proposent un environnement de test pour cela.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Test invoice generation against BIS Billing 3.0';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que la recepción entrante funciona automáticamente', 'El mandato exige recibir facturas estructuradas, no solo enviarlas — asegúrese de que los documentos Peppol entrantes fluyan a su sistema contable sin intervención manual.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Confirm inbound receiving works automatically';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass der Eingang automatisch funktioniert', 'Die Pflicht verlangt, dass Sie strukturierte Rechnungen empfangen, nicht nur versenden — stellen Sie sicher, dass eingehende Peppol-Dokumente ohne manuelle Bearbeitung in Ihr Buchhaltungssystem gelangen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Confirm inbound receiving works automatically';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez que la réception entrante fonctionne automatiquement', 'L''obligation exige que vous receviez des factures structurées, pas seulement que vous en envoyiez — assurez-vous que les documents Peppol entrants alimentent votre système comptable sans traitement manuel.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Confirm inbound receiving works automatically';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure un archivo conforme y a prueba de manipulaciones', 'Confirme que su solución de conservación cumple el mínimo legal de 7 años con una integridad realmente apta para auditoría — no solo almacenamiento de archivos, sino protección demostrable contra la alteración.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Set up compliant, tamper-evident archiving';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine konforme, manipulationssichere Archivierung ein', 'Bestätigen Sie, dass Ihre Aufbewahrungslösung das gesetzliche Minimum von 7 Jahren mit echter prüfungssicherer Integrität erfüllt — nicht nur Dateispeicherung, sondern nachweisbarer Schutz vor Veränderung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Set up compliant, tamper-evident archiving';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage conforme et inviolable', 'Vérifiez que votre solution de conservation respecte le minimum légal de 7 ans avec une intégrité réellement propre à l''audit — pas seulement un stockage de fichiers, mais une protection démontrable contre toute altération.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Belgium' AND dst.title = 'Set up compliant, tamper-evident archiving';

